#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>

int get_rfcomm_devices(void __user *arg) {
    int ret = 0;
    struct rfcomm_dev *dev;
    struct rfcomm_dev_list *user_dev_list = NULL;
    int count = 0;

    if (copy_from_user(&count, arg, sizeof(count)))
        return -EFAULT;

    if (count <= 0)
        return -EINVAL;

    user_dev_list = kmalloc(sizeof(*user_dev_list) + count * sizeof(user_dev_list->devs[0]), GFP_KERNEL);
    if (!user_dev_list)
        return -ENOMEM;

    user_dev_list->count = 0;

    mutex_lock(&rfcomm_dev_lock);
    list_for_each_entry(dev, &rfcomm_dev_list_head, list) {
        if (dev->state != BT_CONNECTED)
            continue;

        if (user_dev_list->count >= count) {
            ret = -ENOSPC;
            break;
        }

        user_dev_list->devs[user_dev_list->count] = *dev;
        user_dev_list->count++;
    }
    mutex_unlock(&rfcomm_dev_lock);

    if (ret < 0)
        goto out;

    if (copy_to_user(arg, user_dev_list, sizeof(*user_dev_list) + user_dev_list->count * sizeof(user_dev_list->devs[0]))) {
        ret = -EFAULT;
    }

out:
    kfree(user_dev_list);
    return ret;
}

#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/mutex.h>
#include <net/bluetooth/bluetooth.h>
#include <net/bluetooth/rfcomm.h>

int get_rfcomm_dev_list(void __user *arg)
{
    int n = 0;
    int err;
    struct rfcomm_dev *d;
    struct rfcomm_dev_info *info = NULL;
    size_t size = 0;

    if (get_user(n, (int __user *)arg))
        return -EFAULT;

    if (n < 0 || n > RFCOMM_MAX_DEV)
        return -EINVAL;

    if (n) {
        size = n * sizeof(struct rfcomm_dev_info);
        info = kmalloc(size, GFP_KERNEL);
        if (!info)
            return -ENOMEM;
    }

    mutex_lock(&rfcomm_dev_list_mutex);

    d = NULL;
    while ((d = rfcomm_dev_iter_next(d))) {
        if (!try_module_get(d->owner))
            continue;

        if (n <= 0) {
            mutex_unlock(&rfcomm_dev_list_mutex);
            err = -ENOBUFS;
            goto out;
        }

        info[n - 1].id = d->id;
        info[n - 1].flags = d->flags;
        info[n - 1].mtu = d->mtu;
        module_put(d->owner);
        n--;
    }

    if (n) {
        err = -ENODEV;
        mutex_unlock(&rfcomm_dev_list_mutex);
        goto out;
    }

    mutex_unlock(&rfcomm_dev_list_mutex);

    if (copy_to_user(arg, info, size)) {
        err = -EFAULT;
        goto out;
    }

    err = 0;

out:
    kfree(info);
    return err;
}

#include <linux/user_namespace.h>
#include <linux/slab.h>
#include <linux/uaccess.h>

int rfcomm_get_devices(void __user *arg) {
    int num_devices;
    struct rfcomm_dev *dev;
    struct rfcomm_dev_info *info;
    struct rfcomm_dev_info *user_info;
    int i = 0;

    if (get_user(num_devices, (int __user *)arg))
        return -EFAULT;

    if (num_devices <= 0)
        return -EINVAL;

    info = kmalloc_array(num_devices, sizeof(struct rfcomm_dev_info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    mutex_lock(&rfcomm_dev_list_lock);

    list_for_each_entry(dev, &rfcomm_dev_list, list) {
        if (i >= num_devices)
            break;
        if (!dev->released) {
            info[i].id = dev->id;
            info[i].flags = dev->flags;
            strscpy(info[i].name, dev->name, sizeof(info[i].name));
            info[i].inuse = dev->inuse;
            i++;
        }
    }

    mutex_unlock(&rfcomm_dev_list_lock);

    if (copy_to_user(arg, info, num_devices * sizeof(struct rfcomm_dev_info))) {
        kfree(info);
        return -EFAULT;
    }

    kfree(info);
    return 0;
}

#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>
#include <linux/rfcomm/core.h>
#include <linux/rfcomm/dev.h>

int rfcomm_get_dev_list(void __user *arg)
{
    int result = -EFAULT;
    int count;
    struct rfcomm_dev **d;
    struct rfcomm_dev_list list;

    if (get_user(count, (int __user *)arg))
        return -EFAULT;

    if (count <= 0)
        return -EINVAL;

    d = kmalloc_array(count, sizeof(*d), GFP_KERNEL);
    if (!d)
        return -ENOMEM;

    spin_lock_bh(&rfcomm_dev_list_lock);

    list.num_devs = 0;
    list.dev = d;

    for (int i = 0; i < RFCOMM_DEV_NUM; i++) {
        struct rfcomm_dev *dev = rfcomm_devs[i];

        if (!dev || dev->state == RFCOMM_DEV_RELEASED)
            continue;

        if (list.num_devs < count)
            list.dev[list.num_devs++] = dev;
        else
            break;
    }

    spin_unlock_bh(&rfcomm_dev_list_lock);

    if (copy_to_user(arg, &list, sizeof(list))) {
        kfree(d);
        return -EFAULT;
    }

    kfree(d);
    return 0;
}

#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>

int rfcomm_get_dev_list(void __user *arg)
{
    int __user *n = arg;
    int ndev, len;
    struct rfcomm_dev *d;
    struct rfcomm_dev **devs;
    int ret = 0;

    if (get_user(ndev, n))
        return -EFAULT;

    if (ndev <= 0)
        return -EINVAL;

    len = ndev * sizeof(struct rfcomm_dev *);
    devs = kmalloc(len, GFP_KERNEL);
    if (!devs)
        return -ENOMEM;

    spin_lock_bh(&rfcomm_dev_lock);

    ndev = 0;
    list_for_each_entry(d, &rfcomm_dev_list, list) {
        if (d->owner != NULL)
            continue;  /* Skip released devices */
        if (ndev < len / sizeof(struct rfcomm_dev *)) {
            devs[ndev] = d;
            ndev++;
        }
    }

    spin_unlock_bh(&rfcomm_dev_lock);

    if (copy_to_user(arg, devs, len)) {
        ret = -EFAULT;
    }

    kfree(devs);
    return ret;
}
